export type EmailBlock = { id: string; type: "heading" | "text" | "image" | "button" | "divider"; content?: string; url?: string; alt?: string; align?: "left" | "center" | "right" };
type TemplateCard = { id?: string | number; name: string; subject: string; category: string; previewText: string | null; contentBlocks: readonly EmailBlock[]; description: string | null; tags?: readonly string[]; status?: "active" | "archived"; isFavorite?: boolean; usageCount?: number; lastUsedAt?: number | null };

const coral = "#ed7664";
const defaultBlocks: EmailBlock[] = [
  { id: "intro", type: "heading", content: "Votre prochaine actualité commence ici", align: "left" },
  { id: "body", type: "text", content: "Écrivez un message utile, clair et centré sur votre audience.", align: "left" },
  { id: "cta", type: "button", content: "Découvrir", url: "https://example.com", align: "left" },
];
const starterTemplates: TemplateCard[] = [
  { id: "mailcraft-editorial", name: "La note éditoriale", subject: "Les idées à retenir cette semaine", category: "Newsletter", previewText: "Une note courte et attentive pour votre audience.", description: "Pour raconter, expliquer et créer un rendez-vous éditorial.", contentBlocks: [{ id: "heading", type: "heading", content: "Une idée à la fois.", align: "left" }, { id: "text", type: "text", content: "Cette semaine, prenons quelques minutes pour partager l’essentiel avec vous.", align: "left" }, { id: "line", type: "divider" }, { id: "button", type: "button", content: "Lire la note", url: "https://example.com", align: "left" }] },
  { id: "mailcraft-launch", name: "Lancement attentif", subject: "Une nouveauté pensée pour vous", category: "Produit", previewText: "Présentez une nouveauté avec simplicité.", description: "Une mise en page structurée pour annoncer un produit ou une évolution.", contentBlocks: [{ id: "heading", type: "heading", content: "Voici ce qui change.", align: "left" }, { id: "text", type: "text", content: "Une amélioration concrète, conçue pour vous faire gagner du temps au quotidien.", align: "left" }, { id: "button", type: "button", content: "Découvrir", url: "https://example.com", align: "left" }] },
  { id: "mailcraft-invitation", name: "Invitation simple", subject: "Vous êtes invité(e)", category: "Événement", previewText: "Une invitation claire, sans surcharge.", description: "Pour présenter le lieu, la date et l’action à suivre avec sobriété.", contentBlocks: [{ id: "heading", type: "heading", content: "Gardez cette date.", align: "center" }, { id: "text", type: "text", content: "Nous serions ravis de vous retrouver pour un moment de partage et de découverte.", align: "center" }, { id: "button", type: "button", content: "Réserver ma place", url: "https://example.com", align: "center" }] },
];

const fmt = new Intl.NumberFormat("fr-FR");
const fmtDate = (value?: number | null) => value ? new Intl.DateTimeFormat("fr-FR", { dateStyle: "medium", timeStyle: "short" }).format(new Date(value)) : "—";
const localDateTime = (value?: number | null) => { if (!value) return ""; const date = new Date(value); date.setMinutes(date.getMinutes() - date.getTimezoneOffset()); return date.toISOString().slice(0, 16); };
const statusLabel: Record<string, string> = { draft: "Brouillon", scheduled: "Planifiée", sending: "Envoi en cours", sent: "Envoyée", active: "Actif", unsubscribed: "Désabonné" };
const statusClass: Record<string, string> = { draft: "bg-[#efebe9] text-[#6b6460]", scheduled: "bg-[#fff0e8] text-[#b65743]", sending: "bg-[#fff5d7] text-[#9b6b00]", sent: "bg-[#e7f4ed] text-[#19724a]", active: "bg-[#e7f4ed] text-[#19724a]", unsubscribed: "bg-[#f2eeee] text-[#756b68]" };

function PageHeader({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description: string; action?: React.ReactNode }) {
  return <header className="mb-8 flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between"><div>{eyebrow && <p className="mb-2 text-[11px] font-bold uppercase tracking-[.16em] text-[#ce6959]">{eyebrow}</p>}<h1 className="text-3xl font-semibold tracking-[-.045em] text-[#282422] sm:text-[34px]">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-[#736d68]">{description}</p></div>{action}</header>;
}

function Metric({ label, value, detail, icon: Icon, tint = "#fff0ed" }: { label: string; value: string; detail: string; icon: typeof Mail; tint?: string }) {
  return <section className="rounded-2xl border border-[#ece6e3] bg-white p-5 shadow-[0_8px_28px_rgba(46,35,31,.035)]"><div className="flex items-start justify-between"><p className="text-sm font-medium text-[#706966]">{label}</p><span className="grid h-8 w-8 place-items-center rounded-xl" style={{ background: tint }}><Icon className="h-4 w-4 text-[#a64f43]" /></span></div><p className="mt-5 text-3xl font-semibold tracking-[-.045em] text-[#282422]">{value}</p><p className="mt-2 text-xs text-[#8a827e]">{detail}</p></section>;
}

export function OverviewPage() {
  const dashboard = trpc.marketing.dashboard.useQuery();
  const [, setLocation] = useLocation();
  if (dashboard.isLoading) return <PageLoading />;
  const data = dashboard.data;
  const trend = (data?.recentCampaigns || []).slice().reverse().map((campaign, index) => ({ label: `#${index + 1}`, ouvertures: campaign.openRate, clics: campaign.clickRate }));
  const deliverabilityTrend = data?.deliverabilityTrend || [];
  const criticalDeliverability = data?.deliverabilityAlerts.filter(alert => alert.critical) || [];
  return <>
    <PageHeader eyebrow="Vue d’ensemble" title="Bonjour, prenez le pouls de vos emails." description="Un aperçu calme des signaux qui comptent pour votre audience." action={<Button onClick={() => setLocation("/campaigns/new")} className="h-10 gap-2 bg-[#ed7664] px-4 text-white hover:bg-[#d96655]"><Plus className="h-4 w-4" />Créer une campagne</Button>} />
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Taux d’ouverture" value={`${data?.openRate ?? 0} %`} detail="Sur l’ensemble des emails envoyés" icon={Mail} /><Metric label="Taux de clics" value={`${data?.clickRate ?? 0} %`} detail="Des destinataires ayant reçu un email" icon={MousePointerClick} tint="#fff6df" /><Metric label="Abonnés" value={fmt.format(data?.subscribers ?? 0)} detail={`${data?.activeSubscribers ?? 0} contacts actifs`} icon={Users} tint="#eaf5ef" /><Metric label="Croissance" value={`+${data?.growth ?? 0}`} detail="Nouveaux abonnés sur 30 jours" icon={BarChart3} tint="#eeeafa" /></div>
    {criticalDeliverability.length > 0 && <section className="mt-6 rounded-2xl border border-[#efb2a8] bg-[#fff4f1] p-5 shadow-[0_8px_28px_rgba(174,66,48,.05)]"><div className="flex items-start gap-3"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-[#ed7664] text-white"><CircleAlert className="h-4 w-4" /></span><div><h2 className="font-semibold tracking-[-.02em] text-[#782d24]">Attention : délivrabilité à surveiller</h2><p className="mt-1 text-sm text-[#8c5149]">Un seuil critique est dépassé. Vérifiez l’audience et les derniers envois avant de lancer une nouvelle campagne.</p><div className="mt-3 flex flex-wrap gap-2">{criticalDeliverability.map(alert => <span key={alert.key} className="rounded-full border border-[#f0bbb2] bg-white px-2.5 py-1 text-xs font-semibold text-[#a94336]">{alert.label} : {alert.rate} % <span className="font-normal text-[#95706b]">(seuil {alert.threshold} %)</span></span>)}</div></div></div></section>}
    <div className="mt-6 grid gap-6 xl:grid-cols-[1.45fr_.9fr]"><section className="min-h-[330px] rounded-2xl border border-[#ece6e3] bg-white p-6 shadow-[0_8px_28px_rgba(46,35,31,.035)]"><div className="flex items-start justify-between"><div><h2 className="font-semibold tracking-[-.025em]">Engagement récent</h2><p className="mt-1 text-xs text-[#807874]">Ouvertures et clics par campagne envoyée.</p></div><span className="rounded-lg bg-[#fff0ed] px-2.5 py-1 text-xs font-medium text-[#bc584a]">Taux en %</span></div>{trend.length ? <div className="mt-7 h-[220px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trend}><defs><linearGradient id="openRate" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor={coral} stopOpacity={.26} /><stop offset="100%" stopColor={coral} stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} stroke="#f1ece9" /><XAxis dataKey="label" axisLine={false} tickLine={false} tick={{ fontSize: 11, fill: "#938b86" }} /><YAxis axisLine={false} tickLine={false} tick={{ fontSize: 11, fill: "#938b86" }} width={28} /><Tooltip contentStyle={{ borderRadius: 12, border: "1px solid #ece6e3", fontSize: 12 }} /><Area type="monotone" dataKey="ouvertures" stroke={coral} strokeWidth={2.5} fill="url(#openRate)" /><Area type="monotone" dataKey="clics" stroke="#8575b5" strokeWidth={2} fill="transparent" /></AreaChart></ResponsiveContainer></div> : <div className="mt-10 grid h-[200px] place-items-center rounded-xl border border-dashed border-[#e6dfdb] text-center"><div><BarChart3 className="mx-auto h-5 w-5 text-[#c5bbb6]" /><p className="mt-3 text-sm font-medium text-[#5d5652]">Vos premiers signaux apparaîtront ici.</p><p className="mt-1 text-xs text-[#938b86]">Envoyez une campagne pour commencer le suivi.</p></div></div>}</section>
      <section className="rounded-2xl border border-[#ece6e3] bg-[#282422] p-6 text-white shadow-[0_8px_28px_rgba(46,35,31,.08)]"><p className="text-xs font-bold uppercase tracking-[.15em] text-[#ff9c8e]">Prochaine étape</p><h2 className="mt-4 text-2xl font-semibold tracking-[-.035em]">Un email clair est déjà un bon début.</h2><p className="mt-3 text-sm leading-6 text-white/60">Choisissez un modèle, adaptez le message et ciblez le bon segment sans quitter votre espace de travail.</p><button onClick={() => setLocation("/templates")} className="mt-7 flex items-center gap-2 text-sm font-medium text-white hover:text-[#ffb1a5]">Explorer les modèles <ArrowRight className="h-4 w-4" /></button><div className="mt-10 flex items-center gap-2 text-xs text-white/45"><span className="h-2 w-2 rounded-full bg-[#ed7664]" />Prêt à créer</div></section></div>
    <section className="mt-6 min-h-[320px] rounded-2xl border border-[#ece6e3] bg-white p-6 shadow-[0_8px_28px_rgba(46,35,31,.035)]"><div className="flex items-start justify-between"><div><h2 className="font-semibold tracking-[-.025em]">Délivrabilité</h2><p className="mt-1 text-xs text-[#807874]">Évolution quotidienne des rebonds et désabonnements sur les 30 derniers jours.</p></div><span className="rounded-lg bg-[#f2eeee] px-2.5 py-1 text-xs font-medium text-[#806f6b]">Taux en %</span></div>{deliverabilityTrend.length ? <div className="mt-7 h-[205px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={deliverabilityTrend}><defs><linearGradient id="bounceRate" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#bc584a" stopOpacity={.2} /><stop offset="100%" stopColor="#bc584a" stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} stroke="#f1ece9" /><XAxis dataKey="date" axisLine={false} tickLine={false} tickFormatter={value => value.slice(5)} tick={{ fontSize: 11, fill: "#938b86" }} /><YAxis axisLine={false} tickLine={false} tick={{ fontSize: 11, fill: "#938b86" }} width={30} /><Tooltip labelFormatter={value => `Date : ${value}`} formatter={(value: number, key: string) => [`${value} %`, key === "tauxRebond" ? "Taux de rebond" : "Taux de désabonnement"]} contentStyle={{ borderRadius: 12, border: "1px solid #ece6e3", fontSize: 12 }} /><Area type="monotone" dataKey="tauxRebond" stroke="#bc584a" strokeWidth={2.4} fill="url(#bounceRate)" /><Area type="monotone" dataKey="tauxDesabonnement" stroke="#8575b5" strokeWidth={2.2} fill="transparent" /></AreaChart></ResponsiveContainer></div> : <div className="mt-8 grid h-[180px] place-items-center rounded-xl border border-dashed border-[#e6dfdb] text-center"><div><Users className="mx-auto h-5 w-5 text-[#c5bbb6]" /><p className="mt-3 text-sm font-medium text-[#5d5652]">Aucun signal de délivrabilité à afficher.</p><p className="mt-1 text-xs text-[#938b86]">Les rebonds et désabonnements apparaîtront ici dès qu’ils seront enregistrés.</p></div></div>}</section>
    <section className="mt-6 rounded-2xl border border-[#ece6e3] bg-white p-6 shadow-[0_8px_28px_rgba(46,35,31,.035)]"><div className="flex items-center justify-between"><div><h2 className="font-semibold tracking-[-.025em]">Campagnes récentes</h2><p className="mt-1 text-xs text-[#807874]">Les derniers brouillons, envois et planifications.</p></div><Link href="/campaigns" className="text-sm font-medium text-[#bd5749] hover:text-[#974235]">Voir toutes</Link></div>{data?.recentCampaigns?.length ? <div className="mt-5 divide-y divide-[#f0ece9]">{data.recentCampaigns.map(campaign => <Link key={campaign.id} href={`/campaigns/${campaign.id}`} className="flex items-center gap-4 py-3.5 hover:bg-[#fcfbfa]"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#fff0ed] text-[#c35e50]"><Send className="h-4 w-4" /></span><span className="min-w-0 flex-1"><strong className="block truncate text-sm font-medium">{campaign.title}</strong><small className="block truncate pt-0.5 text-xs text-[#867e79]">{campaign.subject}</small></span><span className={cn("rounded-full px-2.5 py-1 text-xs font-medium", statusClass[campaign.status])}>{statusLabel[campaign.status]}</span><ArrowRight className="hidden h-4 w-4 text-[#b5aba6] sm:block" /></Link>)}</div> : <EmptyState compact label="Aucune campagne pour le moment." detail="Créez un brouillon pour voir son activité ici." actionLabel="Créer une campagne" onAction={() => setLocation("/campaigns/new")} />}</section>
  </>;
}

export function SubscribersPage() {
  const subscribers = trpc.marketing.subscribers.list.useQuery();
  const utils = trpc.useUtils();
  const [dialogOpen, setDialogOpen] = useState(false); const [importOpen, setImportOpen] = useState(false); const [email, setEmail] = useState(""); const [firstName, setFirstName] = useState(""); const [tags, setTags] = useState(""); const [csv, setCsv] = useState(""); const fileRef = useRef<HTMLInputElement>(null);
  const refresh = () => utils.marketing.subscribers.list.invalidate();
  const create = trpc.marketing.subscribers.create.useMutation({ onSuccess: () => { toast.success("Abonné ajouté."); setDialogOpen(false); setEmail(""); setFirstName(""); setTags(""); refresh(); }, onError: err => toast.error(err.message) });
  const importCsv = trpc.marketing.subscribers.importCsv.useMutation({ onSuccess: result => { toast.success(`${result.imported} abonné(s) importé(s).`); setImportOpen(false); setCsv(""); refresh(); }, onError: err => toast.error(err.message) });
  const deleteSubscriber = trpc.marketing.subscribers.delete.useMutation({ onSuccess: () => { toast.success("Abonné supprimé."); refresh(); } });
  const setStatus = trpc.marketing.subscribers.setStatus.useMutation({ onSuccess: () => refresh() });
  const handleFile = (file?: File) => { if (!file) return; const reader = new FileReader(); reader.onload = () => setCsv(String(reader.result || "")); reader.readAsText(file); };
  return <><PageHeader eyebrow="Audience" title="Vos abonnés, à votre rythme." description="Ajoutez, importez et gardez une base d’audience propre et respectueuse." action={<div className="flex gap-2"><Button variant="outline" onClick={() => setImportOpen(true)} className="h-10 gap-2 border-[#e5ddd9] bg-white"><Upload className="h-4 w-4" />Importer</Button><Button onClick={() => setDialogOpen(true)} className="h-10 gap-2 bg-[#ed7664] text-white hover:bg-[#d96655]"><Plus className="h-4 w-4" />Ajouter</Button></div>} />
    <div className="grid gap-4 sm:grid-cols-3"><MiniStat label="Total" value={fmt.format(subscribers.data?.length ?? 0)} /><MiniStat label="Actifs" value={fmt.format(subscribers.data?.filter(row => row.status === "active").length ?? 0)} accent="text-[#297453]" /><MiniStat label="Désabonnés" value={fmt.format(subscribers.data?.filter(row => row.status === "unsubscribed").length ?? 0)} accent="text-[#7b726e]" /></div>
    <section className="mt-6 overflow-hidden rounded-2xl border border-[#ece6e3] bg-white shadow-[0_8px_28px_rgba(46,35,31,.035)]">{subscribers.isLoading ? <PageLoading /> : subscribers.data?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left"><thead className="border-b border-[#efeae7] bg-[#fcfbfa]"><tr className="text-[11px] font-bold uppercase tracking-[.12em] text-[#8d8580]"><th className="px-6 py-4">Contact</th><th className="px-4 py-4">Tags</th><th className="px-4 py-4">Inscription</th><th className="px-4 py-4">Statut</th><th className="px-6 py-4 text-right">Action</th></tr></thead><tbody>{subscribers.data.map(row => <tr key={row.id} className="border-b border-[#f1ece9] last:border-0"><td className="px-6 py-4"><strong className="block text-sm font-medium">{[row.firstName, row.lastName].filter(Boolean).join(" ") || "Sans nom"}</strong><span className="mt-0.5 block text-xs text-[#837b76]">{row.email}</span></td><td className="px-4 py-4"><div className="flex max-w-[180px] flex-wrap gap-1">{row.tags.length ? row.tags.map((tag: string) => <span key={tag} className="rounded-md bg-[#f5f1ef] px-2 py-1 text-[11px] text-[#746b66]">{tag}</span>) : <span className="text-xs text-[#aaa29e]">—</span>}</div></td><td className="px-4 py-4 text-xs text-[#7f7772]">{fmtDate(row.createdAt)}</td><td className="px-4 py-4"><button onClick={() => setStatus.mutate({ id: row.id, status: row.status === "active" ? "unsubscribed" : "active" })} className={cn("rounded-full px-2.5 py-1 text-xs font-medium", statusClass[row.status])}>{statusLabel[row.status]}</button></td><td className="px-6 py-4 text-right"><button onClick={() => deleteSubscriber.mutate({ id: row.id })} className="rounded-lg p-2 text-[#a29a96] hover:bg-[#fff0ed] hover:text-[#c55647]" aria-label="Supprimer"><Trash2 className="h-4 w-4" /></button></td></tr>)}</tbody></table></div> : <EmptyState label="Votre audience est encore vide." detail="Ajoutez manuellement un premier contact ou importez un fichier CSV contenant une colonne email." actionLabel="Ajouter un abonné" onAction={() => setDialogOpen(true)} />}</section>
    <Dialog open={dialogOpen} onOpenChange={setDialogOpen}><DialogContent><DialogHeader><DialogTitle>Ajouter un abonné</DialogTitle><DialogDescription>Ajoutez un contact à votre audience active.</DialogDescription></DialogHeader><form className="space-y-4" onSubmit={event => { event.preventDefault(); create.mutate({ email, firstName: firstName || undefined, tags: tags.split(",").map(tag => tag.trim()).filter(Boolean) }); }}><div><Label htmlFor="email">Email</Label><Input id="email" className="mt-1.5" type="email" required value={email} onChange={event => setEmail(event.target.value)} /></div><div><Label htmlFor="first">Prénom</Label><Input id="first" className="mt-1.5" value={firstName} onChange={event => setFirstName(event.target.value)} /></div><div><Label htmlFor="tags">Tags</Label><Input id="tags" className="mt-1.5" placeholder="client, webinar, paris" value={tags} onChange={event => setTags(event.target.value)} /></div><Button disabled={create.isPending} className="w-full bg-[#ed7664] text-white hover:bg-[#d96655]">{create.isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}Ajouter à l’audience</Button></form></DialogContent></Dialog>
    <Dialog open={importOpen} onOpenChange={setImportOpen}><DialogContent><DialogHeader><DialogTitle>Importer un fichier CSV</DialogTitle><DialogDescription>Colonnes prises en charge : email, first_name, last_name et tags.</DialogDescription></DialogHeader><input ref={fileRef} type="file" accept=".csv,text/csv" className="hidden" onChange={event => handleFile(event.target.files?.[0])} /><button type="button" onClick={() => fileRef.current?.click()} className="flex min-h-28 w-full flex-col items-center justify-center rounded-xl border border-dashed border-[#e4dcd8] bg-[#fcfbfa] text-sm text-[#706864]"><Upload className="mb-2 h-5 w-5 text-[#bf5b4c]" />{csv ? "Fichier chargé, prêt à importer" : "Choisir un fichier CSV"}</button><Textarea value={csv} onChange={event => setCsv(event.target.value)} className="min-h-28 text-xs" placeholder="Ou collez le contenu CSV ici…" /><Button disabled={!csv || importCsv.isPending} onClick={() => importCsv.mutate({ csv })} className="w-full bg-[#ed7664] text-white hover:bg-[#d96655]">Importer les contacts</Button></DialogContent></Dialog>
  </>;
}

export function SegmentsPage() {
  const segments = trpc.marketing.segments.list.useQuery(); const utils = trpc.useUtils(); const [open, setOpen] = useState(false); const [name, setName] = useState(""); const [description, setDescription] = useState(""); const [tags, setTags] = useState(""); const [status, setStatus] = useState<"active" | "unsubscribed" | "">(""); const [registeredAfter, setRegisteredAfter] = useState("");
  const create = trpc.marketing.segments.create.useMutation({ onSuccess: () => { toast.success("Segment créé."); setOpen(false); setName(""); setDescription(""); setTags(""); setStatus(""); setRegisteredAfter(""); utils.marketing.segments.list.invalidate(); }, onError: err => toast.error(err.message) }); const remove = trpc.marketing.segments.delete.useMutation({ onSuccess: () => { toast.success("Segment supprimé."); utils.marketing.segments.list.invalidate(); } });
  return <><PageHeader eyebrow="Organisation" title="Des segments qui restent humains." description="Regroupez votre audience par intérêt, statut ou ancienneté d’inscription." action={<Button onClick={() => setOpen(true)} className="h-10 gap-2 bg-[#ed7664] text-white hover:bg-[#d96655]"><Plus className="h-4 w-4" />Nouveau segment</Button>} />
    <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{segments.isLoading ? <PageLoading /> : segments.data?.length ? segments.data.map(segment => <section key={segment.id} className="rounded-2xl border border-[#ece6e3] bg-white p-5 shadow-[0_8px_28px_rgba(46,35,31,.035)]"><div className="flex justify-between gap-4"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#eeeafa] text-[#7964a7]"><Tag className="h-4 w-4" /></span><button onClick={() => remove.mutate({ id: segment.id })} className="rounded-lg p-1.5 text-[#aaa19d] hover:bg-[#fff0ed] hover:text-[#bd5547]"><Trash2 className="h-4 w-4" /></button></div><h2 className="mt-6 text-lg font-semibold tracking-[-.03em]">{segment.name}</h2><p className="mt-2 min-h-10 text-sm leading-5 text-[#7f7772]">{segment.description || "Sans description."}</p><div className="mt-5 flex items-center justify-between border-t border-[#f0ece9] pt-4"><span className="text-xs text-[#8a827d]">{segment.criteria.tags?.length ? segment.criteria.tags.join(" · ") : segment.criteria.status ? statusLabel[segment.criteria.status] : "Tous les contacts"}</span><strong className="text-sm text-[#3a3431]">{segment.subscriberCount} contacts</strong></div></section>) : <div className="md:col-span-2 xl:col-span-3"><EmptyState label="Créez votre premier segment." detail="Par exemple : les abonnés actifs tagués “webinar” ou les contacts inscrits récemment." actionLabel="Créer un segment" onAction={() => setOpen(true)} /></div>}</div>
    <Dialog open={open} onOpenChange={setOpen}><DialogContent><DialogHeader><DialogTitle>Nouveau segment</DialogTitle><DialogDescription>Les critères se combinent : les tags doivent tous être présents.</DialogDescription></DialogHeader><form className="space-y-4" onSubmit={event => { event.preventDefault(); create.mutate({ name, description: description || undefined, criteria: { tags: tags.split(",").map(tag => tag.trim()).filter(Boolean), status: status || undefined, registeredAfter: registeredAfter ? new Date(`${registeredAfter}T00:00:00`).getTime() : undefined } }); }}><div><Label htmlFor="segment-name">Nom</Label><Input id="segment-name" className="mt-1.5" required value={name} onChange={event => setName(event.target.value)} placeholder="Clients fidèles" /></div><div><Label htmlFor="segment-description">Description</Label><Input id="segment-description" className="mt-1.5" value={description} onChange={event => setDescription(event.target.value)} placeholder="Optionnelle" /></div><div><Label htmlFor="segment-tags">Tags à inclure</Label><Input id="segment-tags" className="mt-1.5" value={tags} onChange={event => setTags(event.target.value)} placeholder="client, france" /></div><div className="grid grid-cols-2 gap-3"><div><Label htmlFor="segment-status">Statut</Label><select id="segment-status" value={status} onChange={event => setStatus(event.target.value as typeof status)} className="mt-1.5 h-9 w-full rounded-md border border-input bg-transparent px-3 text-sm"><option value="">Tous</option><option value="active">Actif</option><option value="unsubscribed">Désabonné</option></select></div><div><Label htmlFor="segment-date">Inscrit après</Label><Input id="segment-date" className="mt-1.5" type="date" value={registeredAfter} onChange={event => setRegisteredAfter(event.target.value)} /></div></div><Button disabled={create.isPending} className="w-full bg-[#ed7664] text-white hover:bg-[#d96655]">Créer le segment</Button></form></DialogContent></Dialog>
  </>;
}

function OrganizationImageField({ block, onChange }: { block: EmailBlock; onChange: (patch: Partial<EmailBlock>) => void }) {
  const assets = trpc.marketing.assets.list.useQuery();
  const utils = trpc.useUtils();
  const pickerRef = useRef<HTMLInputElement>(null);
  const upload = trpc.marketing.assets.uploadImage.useMutation({
    onSuccess: asset => { onChange({ url: asset.url, alt: block.alt || asset.altText || asset.fileName }); utils.marketing.assets.list.invalidate(); toast.success("Image ajoutée à votre bibliothèque."); },
    onError: error => toast.error(error.message),
  });
  const selectFile = (file?: File) => {
    if (!file) return;
    if (!(["image/jpeg", "image/png", "image/webp", "image/gif"] as string[]).includes(file.type)) { toast.error("Choisissez une image JPG, PNG, WebP ou GIF."); return; }
    if (file.size > 5 * 1024 * 1024) { toast.error("Une image ne peut pas dépasser 5 Mo."); return; }
    const reader = new FileReader();
    reader.onload = () => upload.mutate({ fileName: file.name, contentType: file.type as "image/jpeg" | "image/png" | "image/webp" | "image/gif", dataUrl: String(reader.result), altText: block.alt || undefined });
    reader.onerror = () => toast.error("La lecture du fichier a échoué.");
    reader.readAsDataURL(file);
  };
  return <div className="space-y-2"><input ref={pickerRef} type="file" accept="image/jpeg,image/png,image/webp,image/gif" className="hidden" onChange={event => { selectFile(event.target.files?.[0]); event.currentTarget.value = ""; }} /><div className="flex flex-wrap gap-2"><Button type="button" onClick={() => pickerRef.current?.click()} disabled={upload.isPending} size="sm" variant="outline" className="border-[#e5ddd9]">{upload.isPending ? <Loader2 className="mr-1.5 h-3.5 w-3.5 animate-spin" /> : <Upload className="mr-1.5 h-3.5 w-3.5" />}Téléverser</Button><select defaultValue="library" onChange={event => { const asset = (assets.data ?? []).find(item => String(item.id) === event.target.value); if (asset) onChange({ url: asset.url, alt: block.alt || asset.altText || asset.fileName }); }} className="h-8 min-w-0 flex-1 rounded-md border border-input bg-white px-2 text-xs"><option value="library">Choisir dans la bibliothèque</option>{assets.data?.map(asset => <option key={asset.id} value={asset.id}>{asset.fileName}</option>)}</select></div><Input value={block.url || ""} onChange={event => onChange({ url: event.target.value })} placeholder="URL d’image externe (https://…)" /><Input value={block.alt || ""} onChange={event => onChange({ alt: event.target.value })} placeholder="Texte alternatif" /><p className="text-[11px] leading-4 text-[#948985]">JPG, PNG, WebP ou GIF · 5 Mo maximum · visibles uniquement dans votre organisation.</p></div>;
}

export function TemplatesPage() {
  const [, setLocation] = useLocation(); const utils = trpc.useUtils(); const [query, setQuery] = useState(""); const [category, setCategory] = useState("all"); const [status, setStatus] = useState<"active" | "archived" | "all">("active"); const [favoritesOnly, setFavoritesOnly] = useState(false); const [editorOpen, setEditorOpen] = useState(false); const [editing, setEditing] = useState<TemplateCard | null>(null); const [name, setName] = useState(""); const [subject, setSubject] = useState(""); const [previewText, setPreviewText] = useState(""); const [description, setDescription] = useState(""); const [tagsText, setTagsText] = useState(""); const [editCategory, setEditCategory] = useState("Newsletter"); const [editStatus, setEditStatus] = useState<"active" | "archived">("active"); const [favorite, setFavorite] = useState(false); const [contentBlocks, setContentBlocks] = useState<EmailBlock[]>(defaultBlocks);
  const templates = trpc.marketing.templates.list.useQuery({ query: query || undefined, category: category === "all" ? undefined : category, status, favoritesOnly }); const builtins = trpc.marketing.templates.builtins.useQuery();
  const refresh = () => { utils.marketing.templates.list.invalidate(); utils.marketing.templates.builtins.invalidate(); };
  const create = trpc.marketing.templates.create.useMutation({ onSuccess: result => { toast.success("Modèle créé dans votre bibliothèque."); setEditorOpen(false); refresh(); setEditing(null); }, onError: error => toast.error(error.message) }); const update = trpc.marketing.templates.update.useMutation({ onSuccess: () => { toast.success("Modèle mis à jour."); setEditorOpen(false); refresh(); setEditing(null); }, onError: error => toast.error(error.message) }); const remove = trpc.marketing.templates.delete.useMutation({ onSuccess: () => { toast.success("Modèle supprimé."); refresh(); } }); const duplicate = trpc.marketing.templates.duplicate.useMutation({ onSuccess: () => { toast.success("Copie du modèle créée."); refresh(); } }); const archive = trpc.marketing.templates.archive.useMutation({ onSuccess: () => refresh() }); const toggleFavorite = trpc.marketing.templates.toggleFavorite.useMutation({ onSuccess: () => refresh() }); const applyTemplate = trpc.marketing.templates.applyToCampaign.useMutation({ onSuccess: result => { toast.success("Modèle appliqué au brouillon."); setLocation(`/campaigns/${result.campaignId}`); }, onError: error => toast.error(error.message) }); const applyBuiltin = trpc.marketing.templates.applyBuiltin.useMutation({ onSuccess: result => { toast.success("Modèle MailCraft appliqué au brouillon."); setLocation(`/campaigns/${result.campaignId}`); }, onError: error => toast.error(error.message) });
  const allBuiltins = (builtins.data ?? starterTemplates) as TemplateCard[]; const categoryOptions = Array.from(new Set(["all", ...allBuiltins.map(item => item.category), ...(templates.data?.map(item => item.category) ?? [])])); const visibleBuiltins = allBuiltins.filter(item => (!query || [item.name, item.subject, item.description, item.category].join(" ").toLocaleLowerCase().includes(query.toLocaleLowerCase())) && (category === "all" || item.category === category));
  const openEditor = (template?: TemplateCard) => { const source = template ?? null; setEditing(source); setName(source?.name || ""); setSubject(source?.subject || ""); setPreviewText(source?.previewText || ""); setDescription(source?.description || ""); setTagsText(source?.tags?.join(", ") || ""); setEditCategory(source?.category || "Newsletter"); setEditStatus(source?.status || "active"); setFavorite(source?.isFavorite || false); setContentBlocks(source ? source.contentBlocks.map(block => ({ ...block })) : defaultBlocks.map(block => ({ ...block, id: crypto.randomUUID() }))); setEditorOpen(true); };
  const updateBlock = (index: number, patch: Partial<EmailBlock>) => setContentBlocks(blocks => blocks.map((block, blockIndex) => blockIndex === index ? { ...block, ...patch } : block));
  const addTemplateBlock = (type: EmailBlock["type"]) => { const block: EmailBlock = type === "heading" ? { id: crypto.randomUUID(), type, content: "Un titre qui donne envie", align: "left" } : type === "text" ? { id: crypto.randomUUID(), type, content: "Votre texte ici.", align: "left" } : type === "image" ? { id: crypto.randomUUID(), type, url: "", alt: "Image du modèle", align: "left" } : type === "button" ? { id: crypto.randomUUID(), type, content: "En savoir plus", url: "https://example.com", align: "left" } : { id: crypto.randomUUID(), type }; setContentBlocks(blocks => [...blocks, block]); };
  const saveTemplate = () => { const payload = { name, subject, category: editCategory, description: description || undefined, tags: tagsText.split(",").map(tag => tag.trim()).filter(Boolean), previewText: previewText || undefined, contentBlocks, status: editStatus, isFavorite: favorite }; if (typeof editing?.id === "number") update.mutate({ id: editing.id, ...payload }); else create.mutate(payload); };
  return <><PageHeader eyebrow="Bibliothèque" title="Vos modèles, prêts à évoluer." description="Composez une collection d’emails réutilisables, trouvez la bonne base rapidement et appliquez-la en un clic à un brouillon." action={<Button onClick={() => openEditor()} className="h-10 gap-2 bg-[#ed7664] text-white hover:bg-[#d96655]"><Plus className="h-4 w-4" />Nouveau modèle</Button>} />
    <section className="rounded-2xl border border-[#ece6e3] bg-white p-4 shadow-[0_8px_28px_rgba(46,35,31,.035)]"><div className="grid gap-3 md:grid-cols-[1.3fr_.7fr_.7fr_auto]"><div className="relative"><Search className="pointer-events-none absolute left-3 top-2.5 h-4 w-4 text-[#9d938e]" /><Input value={query} onChange={event => setQuery(event.target.value)} placeholder="Rechercher un modèle, un tag ou un objet…" className="pl-9" /></div><select value={category} onChange={event => setCategory(event.target.value)} className="h-9 rounded-md border border-input bg-transparent px-3 text-sm"><option value="all">Toutes les catégories</option>{categoryOptions.filter(item => item !== "all").map(item => <option key={item} value={item}>{item}</option>)}</select><select value={status} onChange={event => setStatus(event.target.value as typeof status)} className="h-9 rounded-md border border-input bg-transparent px-3 text-sm"><option value="active">Actifs</option><option value="archived">Archivés</option><option value="all">Tous les statuts</option></select><Button onClick={() => setFavoritesOnly(value => !value)} variant={favoritesOnly ? "default" : "outline"} className={cn("h-9", favoritesOnly ? "bg-[#282422] text-white hover:bg-[#403936]" : "border-[#e5ddd9]")}><Star className="mr-1.5 h-3.5 w-3.5" />Favoris</Button></div></section>
    <section className="mt-8"><div className="mb-4 flex items-end justify-between"><div><h2 className="text-sm font-semibold text-[#5e5651]">Collection MailCraft</h2><p className="mt-1 text-xs text-[#908783]">Des structures éditoriales pour partir vite, puis personnaliser à votre manière.</p></div><span className="text-xs text-[#9b918c]">{visibleBuiltins.length} modèle(s)</span></div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{visibleBuiltins.map(template => <TemplatePreview key={template.id ?? template.name} template={template} source="MailCraft" action={<Button onClick={() => typeof template.id === "string" && applyBuiltin.mutate({ templateId: template.id })} disabled={applyBuiltin.isPending} size="sm" className="bg-[#ed7664] text-white hover:bg-[#d96655]">Utiliser</Button>} />)}</div></section>
    <section className="mt-10"><div className="mb-4 flex items-end justify-between"><div><h2 className="text-sm font-semibold text-[#5e5651]">Votre bibliothèque</h2><p className="mt-1 text-xs text-[#908783]">Créez, organisez, archivez ou dupliquez les bases qui vous font gagner du temps.</p></div><span className="text-xs text-[#9b918c]">{templates.data?.length ?? 0} modèle(s)</span></div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{templates.isLoading ? <PageLoading /> : templates.data?.length ? templates.data.map(template => <TemplatePreview key={template.id} template={template} source={template.status === "archived" ? "Archivé" : "Personnel"} action={<div className="flex items-center gap-1"><Button onClick={() => applyTemplate.mutate({ templateId: template.id })} disabled={template.status === "archived" || applyTemplate.isPending} size="sm" className="bg-[#ed7664] text-white hover:bg-[#d96655]">Utiliser</Button><Button onClick={() => openEditor(template)} aria-label="Modifier" size="icon" variant="outline" className="h-8 w-8 border-[#eadfdb]"><Pencil className="h-3.5 w-3.5" /></Button><Button onClick={() => toggleFavorite.mutate({ id: template.id, isFavorite: !template.isFavorite })} aria-label="Favori" size="icon" variant="outline" className={cn("h-8 w-8 border-[#eadfdb]", template.isFavorite && "bg-[#fff4d6] text-[#a26d00]")}><Star className="h-3.5 w-3.5" fill={template.isFavorite ? "currentColor" : "none"} /></Button></div>} footer={<div className="flex flex-wrap gap-2"><button onClick={() => duplicate.mutate({ id: template.id })} className="text-xs text-[#746a65] hover:text-[#b34e40]"><Copy className="mr-1 inline h-3 w-3" />Dupliquer</button><button onClick={() => archive.mutate({ id: template.id, archived: template.status !== "archived" })} className="text-xs text-[#746a65] hover:text-[#b34e40]">{template.status === "archived" ? <><RotateCcw className="mr-1 inline h-3 w-3" />Réactiver</> : <><Archive className="mr-1 inline h-3 w-3" />Archiver</>}</button><button onClick={() => remove.mutate({ id: template.id })} className="text-xs text-[#a35b51] hover:text-[#8d3d32]"><Trash2 className="mr-1 inline h-3 w-3" />Supprimer</button></div>} />) : <div className="md:col-span-2 xl:col-span-3"><EmptyState compact label="Votre bibliothèque est prête à être composée." detail="Créez un modèle ici ou sauvegardez une campagne existante depuis l’éditeur." actionLabel="Créer un modèle" onAction={() => openEditor()} /></div>}</div></section>
    <Dialog open={editorOpen} onOpenChange={setEditorOpen}><DialogContent className="max-h-[92vh] overflow-y-auto sm:max-w-2xl"><DialogHeader><DialogTitle>{editing ? "Modifier le modèle" : "Créer un modèle"}</DialogTitle><DialogDescription>Définissez les métadonnées et le contenu réutilisable de votre email.</DialogDescription></DialogHeader><div className="space-y-4"><div className="grid gap-3 sm:grid-cols-2"><div><Label htmlFor="template-library-name">Nom</Label><Input id="template-library-name" className="mt-1.5" value={name} onChange={event => setName(event.target.value)} placeholder="Newsletter mensuelle" /></div><div><Label htmlFor="template-library-category">Catégorie</Label><Input id="template-library-category" className="mt-1.5" value={editCategory} onChange={event => setEditCategory(event.target.value)} placeholder="Newsletter" /></div></div><div><Label htmlFor="template-library-subject">Objet</Label><Input id="template-library-subject" className="mt-1.5" value={subject} onChange={event => setSubject(event.target.value)} /></div><div><Label htmlFor="template-library-preview">Pré-en-tête</Label><Input id="template-library-preview" className="mt-1.5" value={previewText} onChange={event => setPreviewText(event.target.value)} /></div><div><Label htmlFor="template-library-description">Description</Label><Textarea id="template-library-description" className="mt-1.5 min-h-20" value={description} onChange={event => setDescription(event.target.value)} placeholder="Quand utiliser ce modèle ?" /></div><div><Label htmlFor="template-library-tags">Tags</Label><Input id="template-library-tags" className="mt-1.5" value={tagsText} onChange={event => setTagsText(event.target.value)} placeholder="newsletter, éditorial, produit" /></div><div className="grid gap-3 sm:grid-cols-2"><label className="flex items-center gap-2 rounded-lg border border-[#e8dfdb] px-3 py-2 text-sm"><input type="checkbox" checked={favorite} onChange={event => setFavorite(event.target.checked)} />Marquer comme favori</label><select value={editStatus} onChange={event => setEditStatus(event.target.value as typeof editStatus)} className="h-9 rounded-md border border-input bg-transparent px-3 text-sm"><option value="active">Actif</option><option value="archived">Archivé</option></select></div><div className="border-t border-[#eee6e2] pt-4"><div className="mb-3 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><h3 className="text-sm font-semibold">Contenu du modèle</h3><p className="mt-1 text-xs text-[#8d837e]">Assemblez chaque bloc, puis finalisez si besoin dans l’éditeur de campagne.</p></div><div className="flex gap-2"><select id="template-block-type" className="h-8 rounded-md border border-input bg-white px-2 text-xs" defaultValue="text"><option value="heading">Titre</option><option value="text">Texte</option><option value="image">Image</option><option value="button">Bouton</option><option value="divider">Séparateur</option></select><Button onClick={() => { const control = document.getElementById("template-block-type") as HTMLSelectElement | null; addTemplateBlock((control?.value || "text") as EmailBlock["type"]); }} size="sm" variant="outline" className="h-8 border-[#e5ddd9]"><Plus className="mr-1 h-3.5 w-3.5" />Ajouter</Button></div></div><div className="space-y-2">{contentBlocks.map((block, index) => <div key={block.id} className="rounded-lg border border-[#eee6e2] bg-[#fcfbfa] p-3"><div className="mb-2 flex items-center justify-between"><span className="text-xs font-semibold text-[#6c625e]">{block.type === "heading" ? "Titre" : block.type === "text" ? "Texte" : block.type === "button" ? "Bouton" : block.type === "image" ? "Image" : "Séparateur"}</span><button onClick={() => setContentBlocks(blocks => blocks.filter((_, blockIndex) => blockIndex !== index))} className="text-[#a7685e] hover:text-[#8f4135]"><Trash2 className="h-3.5 w-3.5" /></button></div>{block.type === "divider" ? <hr className="border-[#e6dfdb]" /> : block.type === "image" ? <div className="space-y-2"><Input value={block.url || ""} onChange={event => updateBlock(index, { url: event.target.value })} placeholder="URL de l’image (https://…)" /><Input value={block.alt || ""} onChange={event => updateBlock(index, { alt: event.target.value })} placeholder="Texte alternatif" /></div> : block.type === "button" ? <div className="space-y-2"><Input value={block.content || ""} onChange={event => updateBlock(index, { content: event.target.value })} placeholder="Libellé du bouton" /><Input value={block.url || ""} onChange={event => updateBlock(index, { url: event.target.value })} placeholder="Lien du bouton (https://…)" /></div> : block.type === "text" ? <Textarea value={block.content || ""} onChange={event => updateBlock(index, { content: event.target.value })} className="min-h-20 text-sm" /> : <Input value={block.content || ""} onChange={event => updateBlock(index, { content: event.target.value })} placeholder="Titre" />} {block.type !== "divider" && block.type !== "image" && <select value={block.align || "left"} onChange={event => updateBlock(index, { align: event.target.value as EmailBlock["align"] })} className="mt-2 h-8 rounded-md border border-input bg-white px-2 text-xs"><option value="left">Aligné à gauche</option><option value="center">Centré</option><option value="right">Aligné à droite</option></select>}</div>)}</div></div><Button onClick={saveTemplate} disabled={!name || !subject || !editCategory || !contentBlocks.length || create.isPending || update.isPending} className="w-full bg-[#ed7664] text-white hover:bg-[#d96655]">{create.isPending || update.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Save className="mr-2 h-4 w-4" />}{editing ? "Enregistrer les modifications" : "Créer le modèle"}</Button></div></DialogContent></Dialog>
  </>;
}

function TemplatePreview({ template, action, source, footer }: { template: TemplateCard; action: React.ReactNode; source: string; footer?: React.ReactNode }) { return <section className="overflow-hidden rounded-2xl border border-[#ece6e3] bg-white shadow-[0_8px_28px_rgba(46,35,31,.035)]"><div className="min-h-[170px] bg-[#f8f4f1] p-5"><div className="mx-auto max-w-[230px] rounded-xl bg-white p-4 shadow-[0_8px_22px_rgba(46,35,31,.06)]"><div className="h-1.5 w-8 rounded-full bg-[#ed7664]" /><div className="mt-4 h-3 w-3/4 rounded-full bg-[#37312e]" /><div className="mt-2 h-2 w-full rounded-full bg-[#eee8e4]" /><div className="mt-1.5 h-2 w-[78%] rounded-full bg-[#eee8e4]" /><div className="mt-4 h-6 w-20 rounded-md bg-[#ed7664]" /></div></div><div className="p-5"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><div className="flex items-center gap-2"><span className="text-[11px] font-bold uppercase tracking-[.13em] text-[#c56253]">{template.category}</span>{template.isFavorite && <Star className="h-3.5 w-3.5 fill-[#d49b25] text-[#d49b25]" />}</div><h3 className="mt-1 truncate font-semibold tracking-[-.02em]">{template.name}</h3></div>{action}</div><p className="mt-2 min-h-10 text-sm leading-5 text-[#7c746f]">{template.description || template.previewText || "Modèle prêt à personnaliser."}</p><div className="mt-4 flex flex-wrap gap-1.5">{template.tags?.map(tag => <span key={tag} className="rounded-md bg-[#f4f0ee] px-2 py-1 text-[10px] font-medium text-[#756b66]">{tag}</span>)}{template.status === "archived" && <span className="rounded-md bg-[#f2eeee] px-2 py-1 text-[10px] font-medium text-[#7a6f6b]">Archivé</span>}</div><div className="mt-4 flex items-center justify-between border-t border-[#f0eae7] pt-3"><span className="text-[11px] text-[#9a908b]">{source}{typeof template.usageCount === "number" ? ` · ${template.usageCount} utilisation(s)` : ""}</span>{footer}</div></div></section>; }

export function CampaignsPage() {
  const campaigns = trpc.marketing.campaigns.list.useQuery(); const [, setLocation] = useLocation(); const create = trpc.marketing.campaigns.create.useMutation({ onSuccess: result => setLocation(`/campaigns/${result.id}`), onError: err => toast.error(err.message) }); const duplicate = trpc.marketing.campaigns.duplicate.useMutation({ onSuccess: result => { toast.success("Campagne dupliquée."); setLocation(`/campaigns/${result.id}`); }, onError: error => toast.error(error.message) });
  return <><PageHeader eyebrow="Diffusion" title="Vos campagnes, du brouillon à l’envoi." description="Préparez, planifiez et retrouvez chaque message au même endroit." action={<Button onClick={() => create.mutate({ title: "Nouvelle campagne" })} disabled={create.isPending} className="h-10 gap-2 bg-[#ed7664] text-white hover:bg-[#d96655]"><Plus className="h-4 w-4" />Créer une campagne</Button>} />
    <section className="overflow-hidden rounded-2xl border border-[#ece6e3] bg-white shadow-[0_8px_28px_rgba(46,35,31,.035)]">{campaigns.isLoading ? <PageLoading /> : campaigns.data?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[840px] text-left"><thead className="border-b border-[#efeae7] bg-[#fcfbfa]"><tr className="text-[11px] font-bold uppercase tracking-[.12em] text-[#8d8580]"><th className="px-6 py-4">Campagne</th><th className="px-4 py-4">Audience</th><th className="px-4 py-4">Statut</th><th className="px-4 py-4">Performance</th><th className="px-4 py-4 text-right">Dernière mise à jour</th><th className="px-6 py-4 text-right">Action</th></tr></thead><tbody>{campaigns.data.map(campaign => <tr key={campaign.id} className="border-b border-[#f1ece9] last:border-0 hover:bg-[#fcfbfa]"><td className="px-6 py-4"><Link href={`/campaigns/${campaign.id}`} className="group block"><strong className="block text-sm font-medium group-hover:text-[#b64f42]">{campaign.title}</strong><span className="mt-0.5 block max-w-[280px] truncate text-xs text-[#837b76]">{campaign.subject}</span></Link></td><td className="px-4 py-4 text-xs text-[#746c67]">{campaign.targetSegmentId ? "Segment ciblé" : "Audience active"}</td><td className="px-4 py-4"><span className={cn("rounded-full px-2.5 py-1 text-xs font-medium", statusClass[campaign.status])}>{statusLabel[campaign.status]}</span>{campaign.scheduledFor && campaign.status === "scheduled" && <small className="mt-1 block text-[10px] text-[#9a827a]">{fmtDate(campaign.scheduledFor)}</small>}</td><td className="px-4 py-4 text-xs text-[#746c67]">{campaign.status === "sent" ? `${campaign.openRate}% ouvertures · ${campaign.clickRate}% clics` : "—"}</td><td className="px-4 py-4 text-right text-xs text-[#837b76]">{fmtDate(campaign.updatedAt)}</td><td className="px-6 py-4 text-right"><Button onClick={() => duplicate.mutate({ id: campaign.id })} disabled={duplicate.isPending} size="sm" variant="outline" className="h-8 border-[#e9dfdb] text-xs"><Copy className="mr-1.5 h-3.5 w-3.5" />Dupliquer</Button></td></tr>)}</tbody></table></div> : <EmptyState label="Votre première campagne attend son message." detail="Ouvrez un brouillon et composez un email avec les blocs de votre choix." actionLabel="Créer une campagne" onAction={() => create.mutate({ title: "Nouvelle campagne" })} />}</section>
  </>;
}

export function NewCampaignPage() { const [, setLocation] = useLocation(); const create = trpc.marketing.campaigns.create.useMutation({ onSuccess: result => setLocation(`/campaigns/${result.id}`) }); useEffect(() => { if (!create.isPending && !create.data) create.mutate({ title: "Nouvelle campagne" }); }, []); return <PageLoading label="Création de votre brouillon…" />; }

export function CampaignEditorPage() {
  const [, params] = useRoute("/campaigns/:id"); const id = Number(params?.id); const campaign = trpc.marketing.campaigns.get.useQuery({ id }, { enabled: Number.isInteger(id) && id > 0 }); const segments = trpc.marketing.segments.list.useQuery(); const brandProfiles = trpc.marketing.settings.brandProfiles.list.useQuery(); const personalTemplates = trpc.marketing.templates.list.useQuery(); const builtInTemplates = trpc.marketing.templates.builtins.useQuery(); const utils = trpc.useUtils(); const [, setLocation] = useLocation(); const [title, setTitle] = useState(""); const [subject, setSubject] = useState(""); const [previewText, setPreviewText] = useState(""); const [targetSegmentId, setTargetSegmentId] = useState<number | null>(null); const [blocks, setBlocks] = useState<EmailBlock[]>(defaultBlocks); const [scheduleFor, setScheduleFor] = useState(""); const [dragging, setDragging] = useState<number | null>(null); const [templateOpen, setTemplateOpen] = useState(false); const [templateName, setTemplateName] = useState(""); const [templateCategory, setTemplateCategory] = useState("Personnel"); const [templateDescription, setTemplateDescription] = useState(""); const [templateTags, setTemplateTags] = useState(""); const [selectedTemplate, setSelectedTemplate] = useState(""); const [aiOpen, setAiOpen] = useState(false); const [previewOpen, setPreviewOpen] = useState(false); const [testOpen, setTestOpen] = useState(false); const [testRecipient, setTestRecipient] = useState(""); const [aiObjective, setAiObjective] = useState(""); const [aiLanguage, setAiLanguage] = useState<"français" | "anglais" | "espagnol" | "allemand" | "italien">("français"); const [aiTone, setAiTone] = useState<"professionnel" | "chaleureux" | "direct" | "éditorial">("professionnel"); const [brandTone, setBrandTone] = useState<"sobre" | "premium" | "audacieux" | "bienveillant" | "technique">("sobre"); const [brandProfileId, setBrandProfileId] = useState("none"); const [aiTask, setAiTask] = useState<"draft" | "optimize_subject" | "optimize_content">("draft"); const [previewDevice, setPreviewDevice] = useState<"mobile" | "tablet" | "desktop">("desktop"); const [aiSuggestion, setAiSuggestion] = useState<{ subject: string; previewText: string; heading: string; body: string; ctaLabel: string; rationale: string } | null>(null);
  useEffect(() => { if (campaign.data) { setTitle(campaign.data.title); setSubject(campaign.data.subject); setPreviewText(campaign.data.previewText || ""); setTargetSegmentId(campaign.data.targetSegmentId); setBlocks(campaign.data.contentBlocks); setScheduleFor(localDateTime(campaign.data.scheduledFor)); } }, [campaign.data?.updatedAt]);
  const refresh = () => { utils.marketing.campaigns.get.invalidate({ id }); utils.marketing.campaigns.list.invalidate(); utils.marketing.dashboard.invalidate(); };
  const save = trpc.marketing.campaigns.update.useMutation({ onSuccess: () => { toast.success("Brouillon enregistré."); refresh(); }, onError: err => toast.error(err.message) }); const schedule = trpc.marketing.campaigns.schedule.useMutation({ onSuccess: () => { toast.success("Campagne planifiée."); refresh(); }, onError: err => toast.error(err.message) }); const unschedule = trpc.marketing.campaigns.unschedule.useMutation({ onSuccess: () => { toast.success("Planification annulée."); refresh(); }, onError: err => toast.error(err.message) }); const sendNow = trpc.marketing.campaigns.sendNow.useMutation({ onSuccess: result => { toast.success(`${result.sent} email(s) envoyé(s), ${result.failed} échec(s).`); refresh(); }, onError: err => toast.error(err.message) }); const sendTest = trpc.marketing.campaigns.sendTest.useMutation({ onSuccess: () => { toast.success("Email de test envoyé. Il n’est pas comptabilisé dans les métriques."); setTestOpen(false); }, onError: err => toast.error(err.message) }); const saveTemplate = trpc.marketing.templates.createFromCampaign.useMutation({ onSuccess: () => { toast.success("Modèle enregistré dans votre bibliothèque."); setTemplateOpen(false); setTemplateName(""); setTemplateDescription(""); setTemplateTags(""); utils.marketing.templates.list.invalidate(); } }); const applyPersonalTemplate = trpc.marketing.templates.applyToCampaign.useMutation({ onSuccess: () => { toast.success("Modèle appliqué à cette campagne."); setSelectedTemplate(""); refresh(); }, onError: error => toast.error(error.message) }); const applyBuiltInTemplate = trpc.marketing.templates.applyBuiltin.useMutation({ onSuccess: () => { toast.success("Modèle MailCraft appliqué à cette campagne."); setSelectedTemplate(""); refresh(); }, onError: error => toast.error(error.message) }); const aiAssistant = trpc.marketing.ai.emailAssistant.useMutation({ onSuccess: suggestion => { setAiSuggestion(suggestion); }, onError: error => toast.error(error.message) });
  const canEdit = campaign.data?.status === "draft" || campaign.data?.status === "scheduled";
  const persist = () => save.mutate({ id, title, subject, previewText, targetSegmentId, contentBlocks: blocks });
  const updateBlock = (index: number, patch: Partial<EmailBlock>) => setBlocks(current => current.map((block, blockIndex) => blockIndex === index ? { ...block, ...patch } : block));
  const addBlock = (type: EmailBlock["type"]) => { const created: EmailBlock = type === "heading" ? { id: crypto.randomUUID(), type, content: "Un titre qui donne envie", align: "left" } : type === "text" ? { id: crypto.randomUUID(), type, content: "Votre texte ici.", align: "left" } : type === "button" ? { id: crypto.randomUUID(), type, content: "En savoir plus", url: "https://example.com", align: "left" } : type === "image" ? { id: crypto.randomUUID(), type, url: "", alt: "Image de campagne", align: "left" } : { id: crypto.randomUUID(), type }; setBlocks(current => [...current, created]); };
  const requestAi = () => aiAssistant.mutate({ task: aiTask, language: aiLanguage, tone: aiTone, brandTone, brandProfileId: brandProfileId === "none" ? undefined : Number(brandProfileId), audience: targetSegmentId ? "Segment ciblé" : "Audience active", objective: aiObjective, subject, previewText, blocks });
  const applySuggestion = () => { if (!aiSuggestion) return; setSubject(aiSuggestion.subject); setPreviewText(aiSuggestion.previewText); setBlocks(current => current.map(block => block.type === "heading" ? { ...block, content: aiSuggestion.heading } : block.type === "text" ? { ...block, content: aiSuggestion.body } : block.type === "button" ? { ...block, content: aiSuggestion.ctaLabel } : block)); setAiOpen(false); toast.success("Suggestion IA appliquée au brouillon."); };
  const activePersonalTemplates = (personalTemplates.data ?? []).filter(template => template.status === "active");
  const selectedTemplatePreview = selectedTemplate.startsWith("personal:") ? activePersonalTemplates.find(template => template.id === Number(selectedTemplate.slice("personal:".length))) : selectedTemplate.startsWith("builtin:") ? builtInTemplates.data?.find(template => template.id === selectedTemplate.slice("builtin:".length)) : undefined;
  if (campaign.isLoading) return <PageLoading />; if (campaign.error || !campaign.data) return <EmptyState label="Cette campagne est introuvable." detail="Elle a peut-être été supprimée." actionLabel="Retour aux campagnes" onAction={() => setLocation("/campaigns")} />;
  return <><div className="mb-7 flex flex-wrap items-center justify-between gap-4"><div className="flex items-center gap-3"><button onClick={() => setLocation("/campaigns")} className="grid h-9 w-9 place-items-center rounded-xl border border-[#e7dfdb] bg-white text-[#645b57] hover:bg-[#fff0ed]"><ChevronLeft className="h-4 w-4" /></button><div><p className="text-[11px] font-bold uppercase tracking-[.15em] text-[#c86253]">Éditeur de campagne</p><h1 className="mt-1 text-xl font-semibold tracking-[-.035em]">{campaign.data.status === "sent" ? "Campagne envoyée" : "Composez votre email"}</h1></div></div><div className="flex flex-wrap items-center gap-2"><span className={cn("hidden rounded-full px-2.5 py-1 text-xs font-medium sm:block", statusClass[campaign.data.status])}>{statusLabel[campaign.data.status]}</span>{campaign.data.status === "sent" ? <Button onClick={() => setLocation(`/campaigns/${id}/analytics`)} className="bg-[#282422] text-white hover:bg-[#403936]"><BarChart3 className="mr-2 h-4 w-4" />Voir les analyses</Button> : <><Button onClick={() => setPreviewOpen(true)} variant="outline" className="border-[#e5ddd9] bg-white"><Monitor className="mr-2 h-4 w-4" />Prévisualiser</Button><Button onClick={() => setTestOpen(true)} disabled={!canEdit} variant="outline" className="border-[#e5ddd9] bg-white"><Send className="mr-2 h-4 w-4" />Email de test</Button><Button onClick={() => { setAiOpen(true); setAiSuggestion(null); }} disabled={!canEdit} variant="outline" className="border-[#ead8d3] bg-[#fff8f6] text-[#b64f42] hover:bg-[#fff0ed]"><Sparkles className="mr-2 h-4 w-4" />Assistant IA</Button><Button onClick={persist} disabled={!canEdit || save.isPending} className="bg-[#282422] text-white hover:bg-[#403936]">{save.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Save className="mr-2 h-4 w-4" />}Enregistrer</Button></>}</div></div>
    <div className="grid gap-6 2xl:grid-cols-[320px_minmax(0,1fr)_330px] xl:grid-cols-[290px_minmax(0,1fr)]"><section className="h-max rounded-2xl border border-[#ece6e3] bg-white p-5 shadow-[0_8px_28px_rgba(46,35,31,.035)]"><h2 className="text-sm font-semibold">Réglages</h2><div className="mt-5 space-y-4"><div><Label htmlFor="campaign-title">Nom interne</Label><Input id="campaign-title" disabled={!canEdit} className="mt-1.5" value={title} onChange={event => setTitle(event.target.value)} /></div><div><Label htmlFor="campaign-subject">Objet</Label><Input id="campaign-subject" disabled={!canEdit} className="mt-1.5" value={subject} onChange={event => setSubject(event.target.value)} /></div><div><Label htmlFor="campaign-preview">Pré-en-tête</Label><Input id="campaign-preview" disabled={!canEdit} className="mt-1.5" value={previewText} onChange={event => setPreviewText(event.target.value)} /></div><div><Label htmlFor="campaign-segment">Audience cible</Label><select id="campaign-segment" disabled={!canEdit} value={targetSegmentId ?? "all"} onChange={event => setTargetSegmentId(event.target.value === "all" ? null : Number(event.target.value))} className="mt-1.5 h-9 w-full rounded-md border border-input bg-transparent px-3 text-sm"><option value="all">Toute l’audience active</option>{segments.data?.map(segment => <option key={segment.id} value={segment.id}>{segment.name} · {segment.subscriberCount}</option>)}</select></div></div><div className="mt-6 border-t border-[#f0ebe8] pt-5"><p className="text-xs font-bold uppercase tracking-[.13em] text-[#918783]">Ajouter un bloc</p><div className="mt-3 grid grid-cols-2 gap-2">{([{ type: "text", label: "Texte", icon: FileText }, { type: "image", label: "Image", icon: Image }, { type: "button", label: "Bouton", icon: MousePointerClick }, { type: "divider", label: "Séparateur", icon: SeparatorHorizontal }] as const).map(item => <button key={item.type} disabled={!canEdit} onClick={() => addBlock(item.type)} className="flex items-center gap-2 rounded-lg border border-[#eee6e2] px-2.5 py-2 text-left text-xs text-[#645b57] transition hover:border-[#e89b90] hover:bg-[#fff7f5] disabled:opacity-45"><item.icon className="h-3.5 w-3.5 text-[#c65d50]" />{item.label}</button>)}</div></div><div className="mt-6 border-t border-[#f0ebe8] pt-5"><p className="text-xs font-bold uppercase tracking-[.13em] text-[#918783]">Envoi</p>{campaign.data.status === "scheduled" ? <><p className="mt-3 text-xs leading-5 text-[#736a66]">Prévue le {fmtDate(campaign.data.scheduledFor)}.</p><Button onClick={() => unschedule.mutate({ id })} disabled={unschedule.isPending} variant="outline" className="mt-3 w-full border-[#e7d9d5] text-[#ae4e41]">Annuler la planification</Button></> : <><Input type="datetime-local" disabled={!canEdit} min={localDateTime(Date.now() + 60_000)} value={scheduleFor} onChange={event => setScheduleFor(event.target.value)} className="mt-3" /><Button disabled={!canEdit || !scheduleFor || schedule.isPending} onClick={() => { persist(); schedule.mutate({ id, scheduledFor: new Date(scheduleFor).getTime() }); }} variant="outline" className="mt-2 w-full border-[#e7d9d5] text-[#ae4e41]"><CalendarClock className="mr-2 h-4 w-4" />Planifier</Button><Button disabled={!canEdit || sendNow.isPending} onClick={() => { persist(); sendNow.mutate({ id }); }} className="mt-2 w-full bg-[#ed7664] text-white hover:bg-[#d96655]"><Send className="mr-2 h-4 w-4" />Envoyer maintenant</Button></>}</div><Button disabled={!canEdit} onClick={() => setTemplateOpen(true)} variant="ghost" className="mt-3 w-full text-xs text-[#7f746f] hover:text-[#b34e40]"><LayoutTemplate className="mr-2 h-3.5 w-3.5" />Enregistrer comme modèle</Button></section>
      <section className="order-3 rounded-2xl border border-[#ece6e3] bg-white p-5 shadow-[0_8px_28px_rgba(46,35,31,.035)] xl:order-2"><div className="flex items-center justify-between"><div><h2 className="text-sm font-semibold">Composition</h2><p className="mt-1 text-xs text-[#8d837e]">Glissez les blocs pour modifier leur ordre.</p></div><span className="text-xs text-[#a19893]">{blocks.length} blocs</span></div><div className="mt-5 space-y-3">{blocks.map((block, index) => <article key={block.id} draggable={canEdit} onDragStart={() => setDragging(index)} onDragOver={event => event.preventDefault()} onDrop={() => { if (dragging === null || dragging === index) return; setBlocks(current => { const next = [...current]; const [moved] = next.splice(dragging, 1); next.splice(index, 0, moved); return next; }); setDragging(null); }} className={cn("rounded-xl border p-4 transition", dragging === index ? "border-[#e78578] bg-[#fff8f6] opacity-60" : "border-[#eee8e5] bg-[#fdfcfc]")}><div className="mb-3 flex items-center justify-between"><span className="flex items-center gap-2 text-xs font-semibold text-[#635954]"><span className="h-2 w-2 rounded-full bg-[#ed7664]" />{block.type === "heading" ? "Titre" : block.type === "text" ? "Texte" : block.type === "image" ? "Image" : block.type === "button" ? "Bouton" : "Séparateur"}</span>{canEdit && <button onClick={() => setBlocks(current => current.filter((_, blockIndex) => blockIndex !== index))} className="rounded-md p-1 text-[#a69d98] hover:bg-[#fff0ed] hover:text-[#bd5547]"><Trash2 className="h-3.5 w-3.5" /></button>}</div>{block.type === "divider" ? <div className="py-2"><hr className="border-[#e8e0dc]" /></div> : block.type === "image" ? <div className="space-y-2"><Input disabled={!canEdit} value={block.url || ""} onChange={event => updateBlock(index, { url: event.target.value })} placeholder="URL de l’image (https://…)" /><Input disabled={!canEdit} value={block.alt || ""} onChange={event => updateBlock(index, { alt: event.target.value })} placeholder="Texte alternatif" /></div> : <div className="space-y-2">{block.type === "text" ? <Textarea disabled={!canEdit} value={block.content || ""} onChange={event => updateBlock(index, { content: event.target.value })} className="min-h-24" /> : <Input disabled={!canEdit} value={block.content || ""} onChange={event => updateBlock(index, { content: event.target.value })} />}{block.type === "button" && <Input disabled={!canEdit} value={block.url || ""} onChange={event => updateBlock(index, { url: event.target.value })} placeholder="Lien du bouton (https://…)" />}</div>}</article>)}</div></section>
      <section className="order-2 h-max rounded-2xl border border-[#ece6e3] bg-[#f5f1ef] p-4 shadow-[0_8px_28px_rgba(46,35,31,.035)] xl:order-3"><div className="mb-4 flex items-center justify-between px-1"><div><h2 className="text-sm font-semibold">Aperçu</h2><p className="mt-1 text-xs text-[#8d837e]">Version bureau compacte.</p></div><Monitor className="h-4 w-4 text-[#bc584a]" /></div><EmailPreview subject={subject} previewText={previewText} blocks={blocks} /></section></div>
    <Dialog open={templateOpen} onOpenChange={setTemplateOpen}><DialogContent><DialogHeader><DialogTitle>Enregistrer comme modèle</DialogTitle><DialogDescription>Votre brouillon est enregistré, puis ajouté à votre bibliothèque avec ses métadonnées de réutilisation.</DialogDescription></DialogHeader><div className="space-y-4"><div><Label htmlFor="template-name">Nom du modèle</Label><Input id="template-name" className="mt-1.5" value={templateName} onChange={event => setTemplateName(event.target.value)} placeholder="Newsletter mensuelle" /></div><div className="grid grid-cols-2 gap-3"><div><Label htmlFor="template-category">Catégorie</Label><Input id="template-category" className="mt-1.5" value={templateCategory} onChange={event => setTemplateCategory(event.target.value)} placeholder="Newsletter" /></div><div><Label htmlFor="template-tags">Tags</Label><Input id="template-tags" className="mt-1.5" value={templateTags} onChange={event => setTemplateTags(event.target.value)} placeholder="produit, client" /></div></div><div><Label htmlFor="template-description">Description</Label><Textarea id="template-description" className="mt-1.5 min-h-20" value={templateDescription} onChange={event => setTemplateDescription(event.target.value)} placeholder="Quand utiliser ce modèle ?" /></div><Button disabled={!templateName || !templateCategory || saveTemplate.isPending || save.isPending} onClick={async () => { try { await save.mutateAsync({ id, title, subject, previewText, targetSegmentId, contentBlocks: blocks }); saveTemplate.mutate({ campaignId: id, name: templateName, category: templateCategory, description: templateDescription || undefined, tags: templateTags.split(",").map(tag => tag.trim()).filter(Boolean) }); } catch { /* Le hook de sauvegarde communique déjà l’erreur. */ } }} className="w-full bg-[#ed7664] text-white hover:bg-[#d96655]">{saveTemplate.isPending || save.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Save className="mr-2 h-4 w-4" />}Enregistrer le modèle</Button></div></DialogContent></Dialog>
    <Dialog open={aiOpen} onOpenChange={setAiOpen}><DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-xl"><DialogHeader><DialogTitle className="flex items-center gap-2"><span className="grid h-8 w-8 place-items-center rounded-lg bg-[#fff0ed] text-[#c2584a]"><Sparkles className="h-4 w-4" /></span>Assistant MailCraft</DialogTitle><DialogDescription>Personnalisez la langue et la voix de la marque avant de générer une suggestion que vous gardez libre d’appliquer.</DialogDescription></DialogHeader><div className="space-y-4">{!aiSuggestion ? <><div className="grid grid-cols-2 gap-3"><div><Label htmlFor="ai-task">Action</Label><select id="ai-task" value={aiTask} onChange={event => setAiTask(event.target.value as typeof aiTask)} className="mt-1.5 h-9 w-full rounded-md border border-input bg-transparent px-3 text-sm"><option value="draft">Proposer un email</option><option value="optimize_subject">Optimiser l’objet</option><option value="optimize_content">Optimiser le contenu</option></select></div><div><Label htmlFor="ai-language">Langue</Label><select id="ai-language" value={aiLanguage} onChange={event => setAiLanguage(event.target.value as typeof aiLanguage)} className="mt-1.5 h-9 w-full rounded-md border border-input bg-transparent px-3 text-sm"><option value="français">Français</option><option value="anglais">Anglais</option><option value="espagnol">Espagnol</option><option value="allemand">Allemand</option><option value="italien">Italien</option></select></div><div><Label htmlFor="ai-tone">Ton rédactionnel</Label><select id="ai-tone" value={aiTone} onChange={event => setAiTone(event.target.value as typeof aiTone)} className="mt-1.5 h-9 w-full rounded-md border border-input bg-transparent px-3 text-sm"><option value="professionnel">Professionnel</option><option value="chaleureux">Chaleureux</option><option value="direct">Direct</option><option value="éditorial">Éditorial</option></select></div><div><Label htmlFor="brand-tone">Ton de marque</Label><select id="brand-tone" value={brandTone} onChange={event => setBrandTone(event.target.value as typeof brandTone)} className="mt-1.5 h-9 w-full rounded-md border border-input bg-transparent px-3 text-sm"><option value="sobre">Sobre</option><option value="premium">Premium</option><option value="audacieux">Audacieux</option><option value="bienveillant">Bienveillant</option><option value="technique">Technique</option></select></div><div className="col-span-2"><Label htmlFor="brand-profile">Profil de marque enregistré</Label><select id="brand-profile" value={brandProfileId} onChange={event => setBrandProfileId(event.target.value)} className="mt-1.5 h-9 w-full rounded-md border border-input bg-transparent px-3 text-sm"><option value="none">Aucun profil — utiliser le ton ci-dessus</option>{brandProfiles.data?.map(profile => <option key={profile.id} value={profile.id}>{profile.name} · {profile.tone}</option>)}</select><p className="mt-1.5 text-[11px] text-[#928883]">Créez et gérez vos profils dans Paramètres.</p></div></div><div><Label htmlFor="ai-objective">Objectif de l’email</Label><Textarea id="ai-objective" value={aiObjective} onChange={event => setAiObjective(event.target.value)} className="mt-1.5 min-h-28" placeholder="Ex. annoncer une nouvelle fonctionnalité et encourager l’audience à la découvrir." /></div><Button disabled={!aiObjective || aiAssistant.isPending} onClick={requestAi} className="w-full bg-[#282422] text-white hover:bg-[#403936]">{aiAssistant.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Sparkles className="mr-2 h-4 w-4" />}Générer une suggestion</Button></> : <><section className="rounded-xl border border-[#eee4e0] bg-[#fcfbfa] p-4"><span className="text-[11px] font-bold uppercase tracking-[.14em] text-[#bf5a4c]">Proposition</span><h3 className="mt-2 font-semibold">{aiSuggestion.subject}</h3><p className="mt-1 text-sm text-[#817873]">{aiSuggestion.previewText}</p><div className="mt-4 border-t border-[#eee6e2] pt-4"><p className="text-sm font-medium">{aiSuggestion.heading}</p><p className="mt-2 whitespace-pre-line text-sm leading-6 text-[#665e59]">{aiSuggestion.body}</p><span className="mt-4 inline-block rounded-md bg-[#ed7664] px-3 py-2 text-xs font-semibold text-white">{aiSuggestion.ctaLabel}</span></div></section><p className="rounded-lg bg-[#f4f0ee] p-3 text-xs leading-5 text-[#766d68]"><strong className="text-[#524a46]">Pourquoi cette proposition :</strong> {aiSuggestion.rationale}</p><div className="flex gap-2"><Button onClick={() => setAiSuggestion(null)} variant="outline" className="flex-1 border-[#e6ddd9]">Ajuster la demande</Button><Button onClick={applySuggestion} className="flex-1 bg-[#ed7664] text-white hover:bg-[#d96655]"><Check className="mr-2 h-4 w-4" />Appliquer</Button></div></>}</div></DialogContent></Dialog>
    <Dialog open={testOpen} onOpenChange={setTestOpen}><DialogContent><DialogHeader><DialogTitle>Envoyer un email de test</DialogTitle><DialogDescription>Le test est envoyé uniquement à cette adresse. Il ne modifie ni l’audience ni les statistiques de la campagne.</DialogDescription></DialogHeader><div className="space-y-4"><div><Label htmlFor="test-recipient">Adresse de test</Label><Input id="test-recipient" type="email" value={testRecipient} onChange={event => setTestRecipient(event.target.value)} placeholder="vous@exemple.com" className="mt-1.5" /></div><div className="rounded-lg bg-[#f6f2ef] p-3 text-xs leading-5 text-[#776e69]"><strong className="text-[#534b47]">Objet :</strong> [Test] {subject || "Votre email MailCraft"}</div><Button disabled={!testRecipient || sendTest.isPending} onClick={() => sendTest.mutate({ recipientEmail: testRecipient, subject, previewText, contentBlocks: blocks })} className="w-full bg-[#ed7664] text-white hover:bg-[#d96655]">{sendTest.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Send className="mr-2 h-4 w-4" />}Envoyer le test</Button></div></DialogContent></Dialog>
    <Dialog open={previewOpen} onOpenChange={setPreviewOpen}><DialogContent className="max-h-[92vh] overflow-y-auto sm:max-w-4xl"><DialogHeader><DialogTitle>Prévisualisation de l’email</DialogTitle><DialogDescription>Vérifiez la composition avant de l’enregistrer, de la planifier ou de l’envoyer.</DialogDescription></DialogHeader><div className="flex justify-center gap-2 border-b border-[#eee6e2] pb-4">{([{ id: "mobile", label: "Mobile", icon: Smartphone }, { id: "tablet", label: "Tablette", icon: Tablet }, { id: "desktop", label: "Bureau", icon: Monitor }] as const).map(device => <Button key={device.id} onClick={() => setPreviewDevice(device.id)} size="sm" variant={previewDevice === device.id ? "default" : "outline"} className={cn(previewDevice === device.id ? "bg-[#282422] text-white hover:bg-[#403936]" : "border-[#e5ddd9]")}><device.icon className="mr-1.5 h-3.5 w-3.5" />{device.label}</Button>)}</div><div className="overflow-auto bg-[#f5f1ef] p-5"><div className={cn("mx-auto transition-all duration-200", previewDeviceClass(previewDevice))}><EmailPreview subject={subject} previewText={previewText} blocks={blocks} /></div></div></DialogContent></Dialog>
    <section className="mt-6 rounded-2xl border border-[#ece6e3] bg-white p-5 shadow-[0_8px_28px_rgba(46,35,31,.035)]"><div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[.13em] text-[#c86253]">Bibliothèque de modèles</p><h2 className="mt-1 text-lg font-semibold tracking-[-.03em]">Appliquer une autre composition</h2><p className="mt-1 text-sm text-[#7e7570]">Choisissez un modèle personnel ou MailCraft. Son contenu remplacera le brouillon courant.</p></div><div className="flex w-full max-w-xl gap-2"><select value={selectedTemplate} disabled={!canEdit} onChange={event => setSelectedTemplate(event.target.value)} className="h-10 min-w-0 flex-1 rounded-md border border-input bg-transparent px-3 text-sm"><option value="">Choisir un modèle…</option><optgroup label="Mes modèles">{activePersonalTemplates.map(template => <option key={template.id} value={`personal:${template.id}`}>{template.name} · {template.category}</option>)}</optgroup><optgroup label="Collection MailCraft">{(builtInTemplates.data ?? starterTemplates).map(template => <option key={template.id} value={`builtin:${template.id}`}>{template.name} · {template.category}</option>)}</optgroup></select><Button disabled={!canEdit || !selectedTemplate || applyPersonalTemplate.isPending || applyBuiltInTemplate.isPending} onClick={() => { if (selectedTemplate.startsWith("personal:")) applyPersonalTemplate.mutate({ templateId: Number(selectedTemplate.slice("personal:".length)), campaignId: id }); else if (selectedTemplate.startsWith("builtin:")) applyBuiltInTemplate.mutate({ templateId: selectedTemplate.slice("builtin:".length), campaignId: id }); }} className="shrink-0 bg-[#ed7664] text-white hover:bg-[#d96655]">{applyPersonalTemplate.isPending || applyBuiltInTemplate.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <LayoutTemplate className="mr-2 h-4 w-4" />}Appliquer</Button></div></div>{selectedTemplatePreview && <div className="mt-5 grid gap-5 border-t border-[#eee6e2] pt-5 lg:grid-cols-[.8fr_1.2fr]"><div><h3 className="text-sm font-semibold">Aperçu sélectionné</h3><p className="mt-1 text-xs leading-5 text-[#8a807b]">{selectedTemplatePreview.description || selectedTemplatePreview.previewText || "Modèle prêt à être adapté."}</p><p className="mt-4 text-xs font-semibold text-[#5f5651]">Objet : <span className="font-normal text-[#7f756f]">{selectedTemplatePreview.subject}</span></p></div><div className="max-h-[330px] overflow-auto rounded-xl bg-[#f5f1ef] p-4"><EmailPreview subject={selectedTemplatePreview.subject} previewText={selectedTemplatePreview.previewText || ""} blocks={selectedTemplatePreview.contentBlocks.map(block => ({ ...block }))} /></div></div>}</section>
  </>;
}

export function AnalyticsPage() {
  const [, params] = useRoute("/campaigns/:id/analytics"); const id = Number(params?.id); const analytics = trpc.marketing.campaigns.analytics.useQuery({ id }, { enabled: id > 0 }); const [, setLocation] = useLocation();
  if (analytics.isLoading) return <PageLoading />; if (!analytics.data) return <EmptyState label="Analyses indisponibles." detail="La campagne est introuvable ou n’a pas encore été envoyée." actionLabel="Retour aux campagnes" onAction={() => setLocation("/campaigns")} />;
  const cumulative = analytics.data.timeline.reduce<{ label: string; ouvertures: number; clics: number; sent: number }[]>((rows, item, index) => { const previous = rows[index - 1] || { ouvertures: 0, clics: 0, sent: 0 }; rows.push({ label: `#${index + 1}`, ouvertures: previous.ouvertures + item.opened, clics: previous.clics + item.clicked, sent: previous.sent + item.sent }); return rows; }, []);
  return <><PageHeader eyebrow="Performances" title={analytics.data.campaign.title} description="Les indicateurs mesurés pour cette campagne une fois les emails diffusés." action={<Button onClick={() => setLocation(`/campaigns/${id}`)} variant="outline" className="border-[#e5ddd9] bg-white"><ChevronLeft className="mr-1 h-4 w-4" />Campagne</Button>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Emails envoyés" value={fmt.format(analytics.data.sent)} detail="Livraisons réussies" icon={Send} /><Metric label="Ouvertures" value={`${analytics.data.openRate} %`} detail={`${analytics.data.opened} ouvertures uniques`} icon={Mail} /><Metric label="Clics" value={`${analytics.data.clickRate} %`} detail={`${analytics.data.clicked} clics uniques`} icon={MousePointerClick} tint="#fff6df" /><Metric label="Désabonnements" value={fmt.format(analytics.data.unsubscribed)} detail="Préférences mises à jour" icon={Users} tint="#f2eeee" /></div><section className="mt-6 min-h-[390px] rounded-2xl border border-[#ece6e3] bg-white p-6 shadow-[0_8px_28px_rgba(46,35,31,.035)]"><h2 className="font-semibold tracking-[-.025em]">Évolution des signaux</h2><p className="mt-1 text-xs text-[#807874]">Cumul des ouvertures et clics enregistrés.</p>{cumulative.length ? <div className="mt-7 h-[270px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={cumulative}><defs><linearGradient id="analyticsOpen" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor={coral} stopOpacity={.25} /><stop offset="100%" stopColor={coral} stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} stroke="#f1ece9" /><XAxis dataKey="label" axisLine={false} tickLine={false} tick={{ fontSize: 11, fill: "#938b86" }} /><YAxis axisLine={false} tickLine={false} tick={{ fontSize: 11, fill: "#938b86" }} width={28} /><Tooltip contentStyle={{ borderRadius: 12, border: "1px solid #ece6e3", fontSize: 12 }} /><Area type="monotone" dataKey="ouvertures" stroke={coral} strokeWidth={2.5} fill="url(#analyticsOpen)" /><Area type="monotone" dataKey="clics" stroke="#8575b5" strokeWidth={2} fill="transparent" /></AreaChart></ResponsiveContainer></div> : <EmptyState compact label="Aucun événement mesuré pour l’instant." detail="Les ouvertures et clics apparaîtront ici à mesure que les destinataires interagissent." />}</section></>;
}

function EmailPreview({ subject, previewText, blocks }: { subject: string; previewText: string; blocks: EmailBlock[] }) { return <div className="overflow-hidden rounded-xl border border-[#e7dfdb] bg-white shadow-[0_12px_34px_rgba(46,35,31,.08)]"><div className="border-b border-[#f0eae7] px-4 py-3"><p className="truncate text-[11px] font-medium text-[#5e5652]">{subject || "Objet de votre email"}</p><p className="mt-0.5 truncate text-[10px] text-[#a19893]">{previewText || "Pré-en-tête de votre campagne"}</p></div><article className="min-h-[340px] p-5 sm:p-7">{blocks.map(block => { const align = block.align || "left"; if (block.type === "heading") return <h3 key={block.id} className="mb-4 text-xl font-semibold tracking-[-.04em] text-[#282422]" style={{ textAlign: align }}>{block.content}</h3>; if (block.type === "text") return <p key={block.id} className="mb-5 whitespace-pre-line text-sm leading-6 text-[#655d59]" style={{ textAlign: align }}>{block.content}</p>; if (block.type === "divider") return <hr key={block.id} className="my-6 border-[#ece5e1]" />; if (block.type === "image") return block.url ? <img key={block.id} src={block.url} alt={block.alt || ""} className="mb-5 max-h-48 w-full rounded-lg object-cover" /> : <div key={block.id} className="mb-5 grid h-24 place-items-center rounded-lg bg-[#f5f1ef] text-xs text-[#9d938e]"><Image className="mr-1 inline h-3.5 w-3.5" />Image</div>; return <div key={block.id} className="mb-5" style={{ textAlign: align }}><span className="inline-block rounded-md bg-[#ed7664] px-4 py-2.5 text-xs font-semibold text-white">{block.content || "Bouton"}</span></div>; })}</article><div className="border-t border-[#f0eae7] px-5 py-3 text-[10px] text-[#a39994]">Email envoyé avec MailCraft · Gérer mes préférences</div></div>; }

function MiniStat({ label, value, accent = "text-[#282422]" }: { label: string; value: string; accent?: string }) { return <section className="rounded-2xl border border-[#ece6e3] bg-white p-5"><p className="text-xs text-[#827a75]">{label}</p><p className={cn("mt-2 text-2xl font-semibold tracking-[-.04em]", accent)}>{value}</p></section>; }
function EmptyState({ label, detail, actionLabel, onAction, compact = false }: { label: string; detail: string; actionLabel?: string; onAction?: () => void; compact?: boolean }) { return <div className={cn("grid place-items-center text-center", compact ? "min-h-40 px-5 py-8" : "min-h-[270px] px-6 py-12")}><div className="max-w-sm"><span className="mx-auto grid h-10 w-10 place-items-center rounded-xl bg-[#fff0ed] text-[#bf594b]"><CircleAlert className="h-4 w-4" /></span><h2 className="mt-4 text-base font-semibold tracking-[-.02em] text-[#443d39]">{label}</h2><p className="mt-2 text-sm leading-6 text-[#817874]">{detail}</p>{actionLabel && onAction && <Button onClick={onAction} className="mt-5 bg-[#ed7664] text-white hover:bg-[#d96655]">{actionLabel}</Button>}</div></div>; }
function PageLoading({ label = "Chargement de votre espace…" }: { label?: string }) { return <div className="grid min-h-[260px] place-items-center"><div className="text-center"><Loader2 className="mx-auto h-5 w-5 animate-spin text-[#d66455]" /><p className="mt-3 text-sm text-[#887f7b]">{label}</p></div></div>; }
